from pathlib import Path

def write(path: str, content: str) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')

write('app/services/nws.py', 'from __future__ import annotations\n\nfrom typing import Any\n\nimport httpx\n\nfrom app.core.config import get_settings\n\n\nclass NWSClient:\n    def __init__(self) -> None:\n        settings = get_settings()\n        self.base_url = settings.nws_api_url.rstrip("/")\n        self.timeout = settings.http_timeout_seconds\n        self.headers = {"User-Agent": settings.http_user_agent, "Accept": "application/geo+json"}\n\n    def latest_observation(self, station_code: str) -> dict[str, Any]:\n        with httpx.Client(timeout=self.timeout, headers=self.headers) as client:\n            response = client.get(f"{self.base_url}/stations/{station_code}/observations/latest")\n            response.raise_for_status()\n            payload = response.json()\n        properties = payload.get("properties", {})\n\n        def value(name: str) -> Any:\n            entry = properties.get(name)\n            return entry.get("value") if isinstance(entry, dict) else entry\n\n        return {\n            "station_code": station_code,\n            "observation_time": properties.get("timestamp"),\n            "temperature_c": value("temperature"),\n            "dew_point_c": value("dewpoint"),\n            "humidity": value("relativeHumidity"),\n            "wind_speed_m_s": value("windSpeed"),\n            "wind_direction": value("windDirection"),\n            "pressure_pa": value("barometricPressure"),\n            "raw_payload": payload,\n        }\n')
write('app/services/open_meteo.py', 'from __future__ import annotations\n\nfrom datetime import date\nfrom typing import Any\n\nimport httpx\nimport pandas as pd\n\nfrom app.core.config import get_settings\n\n\nclass OpenMeteoClient:\n    def __init__(self) -> None:\n        settings = get_settings()\n        self.archive_url = settings.open_meteo_archive_url\n        self.historical_forecast_url = settings.open_meteo_historical_forecast_url\n        self.timeout = settings.http_timeout_seconds\n        self.headers = {"User-Agent": settings.http_user_agent, "Accept": "application/json"}\n\n    def _get(self, url: str, params: dict[str, Any]) -> dict[str, Any]:\n        with httpx.Client(timeout=self.timeout, headers=self.headers) as client:\n            response = client.get(url, params=params)\n            response.raise_for_status()\n            return response.json()\n\n    def fetch_archive_daily(\n        self,\n        *,\n        latitude: float,\n        longitude: float,\n        start_date: date,\n        end_date: date,\n    ) -> pd.DataFrame:\n        payload = self._get(\n            self.archive_url,\n            {\n                "latitude": latitude,\n                "longitude": longitude,\n                "start_date": start_date.isoformat(),\n                "end_date": end_date.isoformat(),\n                "daily": ",".join(\n                    [\n                        "temperature_2m_max",\n                        "temperature_2m_min",\n                        "precipitation_sum",\n                        "wind_speed_10m_max",\n                        "shortwave_radiation_sum",\n                    ]\n                ),\n                "temperature_unit": "fahrenheit",\n                "wind_speed_unit": "mph",\n                "timezone": "UTC",\n            },\n        )\n        daily = payload.get("daily") or {}\n        frame = pd.DataFrame(daily)\n        if frame.empty:\n            raise ValueError("Open-Meteo archive returned no daily data.")\n        return frame.rename(\n            columns={\n                "time": "target_time",\n                "temperature_2m_max": "actual_value",\n                "temperature_2m_min": "actual_low",\n                "precipitation_sum": "actual_precipitation",\n                "wind_speed_10m_max": "actual_wind_speed",\n                "shortwave_radiation_sum": "actual_solar_radiation",\n            }\n        )\n\n    def fetch_historical_forecast_daily(\n        self,\n        *,\n        latitude: float,\n        longitude: float,\n        start_date: date,\n        end_date: date,\n    ) -> pd.DataFrame:\n        payload = self._get(\n            self.historical_forecast_url,\n            {\n                "latitude": latitude,\n                "longitude": longitude,\n                "start_date": start_date.isoformat(),\n                "end_date": end_date.isoformat(),\n                "daily": ",".join(\n                    [\n                        "temperature_2m_max",\n                        "temperature_2m_min",\n                        "precipitation_probability_max",\n                        "wind_speed_10m_max",\n                    ]\n                ),\n                "temperature_unit": "fahrenheit",\n                "wind_speed_unit": "mph",\n                "timezone": "UTC",\n            },\n        )\n        daily = payload.get("daily") or {}\n        frame = pd.DataFrame(daily)\n        if frame.empty:\n            raise ValueError("Open-Meteo historical forecast returned no daily data.")\n        return frame.rename(\n            columns={\n                "time": "target_time",\n                "temperature_2m_max": "forecast_mean",\n                "temperature_2m_min": "forecast_low",\n                "precipitation_probability_max": "precipitation_probability",\n                "wind_speed_10m_max": "wind_speed",\n            }\n        )\n\n    def build_training_dataset(\n        self,\n        *,\n        station_code: str,\n        latitude: float,\n        longitude: float,\n        elevation_m: float | None,\n        start_date: date,\n        end_date: date,\n        market_type: str,\n        assumed_lead_hours: int,\n    ) -> pd.DataFrame:\n        actual = self.fetch_archive_daily(\n            latitude=latitude,\n            longitude=longitude,\n            start_date=start_date,\n            end_date=end_date,\n        )\n        forecast = self.fetch_historical_forecast_daily(\n            latitude=latitude,\n            longitude=longitude,\n            start_date=start_date,\n            end_date=end_date,\n        )\n        frame = forecast.merge(actual, on="target_time", how="inner")\n        frame["target_time"] = pd.to_datetime(frame["target_time"], utc=True)\n        frame["station_code"] = station_code\n        frame["market_type"] = market_type\n        frame["latitude"] = latitude\n        frame["longitude"] = longitude\n        frame["elevation_m"] = elevation_m or 0.0\n        frame["lead_hours"] = assumed_lead_hours\n        frame["forecast_median"] = frame["forecast_mean"]\n        frame["forecast_min"] = frame["forecast_mean"] - 1.5\n        frame["forecast_max"] = frame["forecast_mean"] + 1.5\n        frame["forecast_std"] = 1.5\n        frame["model_count"] = 1\n        frame["data_age_seconds"] = assumed_lead_hours * 3600\n        return frame\n')
write('app/services/outcome_service.py', 'from __future__ import annotations\n\nfrom sqlalchemy.orm import Session\n\nfrom app.db.models import OutcomeRecord, PredictionEvaluation, PredictionRecord\nfrom app.ml.distributions import binary_log_loss\nfrom app.schemas.outcome import OutcomeCreate\n\n\ndef record_outcome(db: Session, payload: OutcomeCreate) -> tuple[OutcomeRecord, int]:\n    outcome = db.query(OutcomeRecord).filter(OutcomeRecord.market_id == payload.market_id).one_or_none()\n    if outcome is None:\n        outcome = OutcomeRecord(\n            market_id=payload.market_id,\n            station_code=payload.station_code,\n            official_value=payload.official_value,\n            official_source=payload.official_source,\n            settled_at=payload.settled_at,\n            metadata_json=payload.metadata,\n        )\n        db.add(outcome)\n        db.flush()\n    else:\n        outcome.station_code = payload.station_code\n        outcome.official_value = payload.official_value\n        outcome.official_source = payload.official_source\n        outcome.settled_at = payload.settled_at\n        outcome.metadata_json = payload.metadata\n\n    predictions = (\n        db.query(PredictionRecord)\n        .filter(PredictionRecord.market_id == payload.market_id)\n        .all()\n    )\n    created = 0\n    for prediction in predictions:\n        existing = (\n            db.query(PredictionEvaluation)\n            .filter(PredictionEvaluation.prediction_id == prediction.id)\n            .one_or_none()\n        )\n        if existing:\n            continue\n        error = prediction.predicted_value - payload.official_value\n        event_outcome = None\n        brier = None\n        log_loss = None\n        if prediction.calibrated_probability is not None:\n            event_outcome = int(\n                (prediction.lower_bound is None or payload.official_value >= prediction.lower_bound)\n                and (prediction.upper_bound is None or payload.official_value < prediction.upper_bound)\n            )\n            brier = (prediction.calibrated_probability - event_outcome) ** 2\n            log_loss = binary_log_loss(prediction.calibrated_probability, event_outcome)\n        evaluation = PredictionEvaluation(\n            prediction_id=prediction.id,\n            outcome_id=outcome.id,\n            absolute_error=abs(error),\n            squared_error=error**2,\n            brier_score=brier,\n            log_loss=log_loss,\n            event_outcome=event_outcome,\n        )\n        db.add(evaluation)\n        created += 1\n    db.commit()\n    db.refresh(outcome)\n    return outcome, created\n')
